CREATE OR REPLACE FUNCTION public.claim_worker_invitations()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_phone TEXT;
    v_inv RECORD;
    v_claims_processed INTEGER := 0;
BEGIN
    -- Validate caller
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Get verified phone directly from Supabase Auth
    SELECT phone INTO v_phone FROM auth.users WHERE id = auth.uid();
    IF v_phone IS NULL THEN
        RAISE EXCEPTION 'No verified phone number associated with this account';
    END IF;

    v_phone := public.canonicalize_phone(v_phone);

    -- Find and claim all PENDING invitations for this phone across all organizations
    -- Use FOR UPDATE to prevent concurrent claiming race conditions
    FOR v_inv IN
        SELECT * FROM public.worker_invitations
        WHERE phone_number = v_phone
          AND status = 'PENDING'
          AND expires_at > NOW()
        FOR UPDATE SKIP LOCKED
    LOOP
        -- 1. Insert/Update Organization Membership
        -- Using ON CONFLICT to handle edge cases where they were added manually
        INSERT INTO public.organization_members (organization_id, profile_id, role, is_active)
        VALUES (v_inv.organization_id, auth.uid(), v_inv.role, true)
        ON CONFLICT (organization_id, profile_id)
        DO UPDATE SET is_active = true, role = EXCLUDED.role;

        -- 2. Insert/Update Store Membership
        INSERT INTO public.user_stores (profile_id, store_id, is_active)
        VALUES (auth.uid(), v_inv.store_id, true)
        ON CONFLICT (profile_id, store_id)
        DO UPDATE SET is_active = true;

        -- 3. Mark Invitation Claimed
        UPDATE public.worker_invitations
        SET status = 'CLAIMED', claimed_at = NOW()
        WHERE id = v_inv.id;

        -- If user's profile name is still default 'New User' or they are fresh, update their name
        -- Note: profiles row should exist via on_auth_user_created trigger
        UPDATE public.profiles
        SET full_name = v_inv.intended_name
        WHERE id = auth.uid() AND full_name IN ('New User', '', NULL);

        v_claims_processed := v_claims_processed + 1;
    END LOOP;

    RETURN v_claims_processed;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_product_with_opening_stock(p_organization_id uuid, p_store_id uuid, p_name text, p_sku text, p_purchase_cost numeric, p_selling_price numeric, p_opening_stock_packages integer, p_description text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_image_url text DEFAULT NULL::text, p_barcode text DEFAULT NULL::text, p_attributes jsonb DEFAULT NULL::jsonb, p_tracking_mode tracking_mode DEFAULT 'NONE'::tracking_mode, p_variant_image_url text DEFAULT NULL::text, p_is_active boolean DEFAULT true, p_unit_of_measure text DEFAULT 'PCS'::text, p_packaging_type text DEFAULT 'NONE'::text, p_units_per_pack integer DEFAULT 1, p_item_size numeric DEFAULT 1)
 RETURNS product_creation_result
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_derived_org_id UUID;
    v_result public.product_creation_result;
    v_base_units INTEGER;
BEGIN
    -- 1. Validate caller is authenticated
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- 2. Validate store exists and derive its organization
    SELECT organization_id INTO v_derived_org_id FROM public.stores WHERE id = p_store_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Store not found';
    END IF;

    -- 3. Verify cross-tenant protection
    IF v_derived_org_id != p_organization_id THEN
        RAISE EXCEPTION 'Store does not belong to the specified organization';
    END IF;

    -- 4. Validate caller role (must be MANAGER or OWNER of the derived organization)
    IF NOT public.is_org_manager_or_owner(v_derived_org_id) THEN
        RAISE EXCEPTION 'Unauthorized: Only Managers and Owners can create products';
    END IF;

    -- 5. Calculate base units before starting insertion (Fail fast)
    v_base_units := COALESCE(p_opening_stock_packages, 0) * 
        CASE 
            WHEN p_packaging_type = 'NONE' THEN 1 
            ELSE COALESCE(p_units_per_pack, 1) 
        END;

    IF v_base_units < 0 THEN
        RAISE EXCEPTION 'Opening stock cannot be negative';
    END IF;

    -- 6. Create the product and variant (reusing existing secure logic)
    SELECT * FROM public.create_product_with_variant(
        p_organization_id, p_name, p_sku, p_purchase_cost, p_selling_price, p_description, p_category_id, p_image_url, p_barcode, p_attributes, p_tracking_mode, p_variant_image_url, p_is_active, p_unit_of_measure, p_packaging_type, p_units_per_pack, p_item_size
    ) INTO v_result;

    -- 7. Initialize inventory atomically if requested
    IF v_base_units > 0 THEN
        PERFORM public.record_inventory_movement(
            p_store_id,
            v_result.variant_id,
            'opening_stock',
            v_base_units,
            NULL,
            'Initial opening stock',
            'RESELLABLE'
        );
    END IF;

    RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.invite_worker(p_phone text, p_intended_name text, p_role user_role, p_store_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_org_id UUID;
    v_canonical_phone TEXT;
    v_existing_auth_id UUID;
    v_existing_active BOOLEAN;
    v_invite_id UUID;
BEGIN
    -- Validate caller is authenticated
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Validate role
    IF p_role NOT IN ('MANAGER', 'CASHIER') THEN
        RAISE EXCEPTION 'Can only invite MANAGER or CASHIER';
    END IF;

    -- Resolve and validate organization from store
    SELECT organization_id INTO v_org_id FROM public.stores WHERE id = p_store_id;
    IF v_org_id IS NULL THEN
        RAISE EXCEPTION 'Store not found';
    END IF;

    -- Validate caller is OWNER
    IF NOT public.is_org_owner(v_org_id) THEN
        RAISE EXCEPTION 'Only an OWNER can invite workers';
    END IF;

    -- Canonicalize phone
    v_canonical_phone := public.canonicalize_phone(p_phone);

    -- Check if user already exists in auth.users
    SELECT id INTO v_existing_auth_id FROM auth.users WHERE phone = v_canonical_phone;

    IF v_existing_auth_id IS NOT NULL THEN
        -- User exists in Auth. Check if they already belong to this org.
        SELECT is_active INTO v_existing_active
        FROM public.organization_members
        WHERE organization_id = v_org_id AND profile_id = v_existing_auth_id;

        IF FOUND THEN
            IF v_existing_active THEN
                RAISE EXCEPTION 'User is already an active member of this organization';
            ELSE
                -- Reactivate and update role
                UPDATE public.organization_members
                SET is_active = true, role = p_role
                WHERE organization_id = v_org_id AND profile_id = v_existing_auth_id;

                -- Ensure store membership exists and is active
                INSERT INTO public.user_stores (profile_id, store_id, is_active)
                VALUES (v_existing_auth_id, p_store_id, true)
                ON CONFLICT (profile_id, store_id) DO UPDATE SET is_active = true;

                RETURN NULL; -- Re-activated existing user
            END IF;
        ELSE
            -- User exists in auth but not in this org. Directly insert them!
            INSERT INTO public.organization_members (organization_id, profile_id, role, is_active)
            VALUES (v_org_id, v_existing_auth_id, p_role, true);

            INSERT INTO public.user_stores (profile_id, store_id, is_active)
            VALUES (v_existing_auth_id, p_store_id, true);

            RETURN NULL; -- Created membership directly
        END IF;
    END IF;

    -- User does NOT exist in auth.users. Create or update PENDING invitation.
    -- If a pending invite already exists, cancel it first to avoid unique constraint violations
    UPDATE public.worker_invitations
    SET status = 'CANCELLED', cancelled_at = NOW()
    WHERE organization_id = v_org_id AND phone_number = v_canonical_phone AND status = 'PENDING';

    -- Insert new invitation
    INSERT INTO public.worker_invitations (organization_id, store_id, phone_number, intended_name, role, status, created_by)
    VALUES (v_org_id, p_store_id, v_canonical_phone, p_intended_name, p_role, 'PENDING', auth.uid())
    RETURNING id INTO v_invite_id;

    RETURN v_invite_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_inventory_movement(p_store_id uuid, p_variant_id uuid, p_movement_type movement_type, p_quantity numeric, p_reference_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_disposition return_disposition DEFAULT 'RESELLABLE'::return_disposition)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_balance RECORD;
    v_org_id UUID;
    v_active_reservations NUMERIC;
    v_available_stock NUMERIC;
    v_movement_id UUID;
    v_variant RECORD;
BEGIN
    SELECT organization_id INTO v_org_id FROM public.stores WHERE id = p_store_id;
    IF v_org_id IS NULL THEN RAISE EXCEPTION 'Store not found'; END IF;
    IF NOT public.is_store_member(p_store_id) AND NOT public.is_org_manager_or_owner(v_org_id) THEN 
        IF auth.uid() IS NOT NULL THEN
            RAISE EXCEPTION 'Unauthorized to modify inventory in this store';
        END IF;
    END IF;

    -- Lookup variant to ensure it exists and belongs to the same organization
    SELECT v.*
    INTO v_variant
    FROM public.product_variants v
    JOIN public.products p
      ON v.product_id = p.id
    WHERE v.id = p_variant_id
      AND p.organization_id = v_org_id
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Variant not found or does not belong to your organization';
    END IF;

    SELECT * INTO v_balance FROM public.inventory_balances 
    WHERE store_id = p_store_id AND variant_id = p_variant_id FOR UPDATE;

    IF NOT FOUND THEN
        INSERT INTO public.inventory_balances (store_id, organization_id, variant_id, on_hand_stock, incoming_stock, damaged_stock)
        VALUES (p_store_id, v_org_id, p_variant_id, 0, 0, 0)
        RETURNING * INTO v_balance;
    END IF;

    SELECT COALESCE(SUM(quantity), 0) INTO v_active_reservations 
    FROM public.inventory_reservations 
    WHERE store_id = p_store_id AND variant_id = p_variant_id AND status = 'ACTIVE' AND expires_at > NOW();

    v_available_stock := v_balance.on_hand_stock - v_active_reservations;

    CASE p_movement_type
        WHEN 'opening_stock' THEN
            UPDATE public.inventory_balances SET on_hand_stock = on_hand_stock + p_quantity WHERE id = v_balance.id;
        WHEN 'purchase_received' THEN
            UPDATE public.inventory_balances SET on_hand_stock = on_hand_stock + p_quantity WHERE id = v_balance.id;
        WHEN 'customer_return' THEN
            IF p_disposition = 'RESELLABLE' THEN
                UPDATE public.inventory_balances SET on_hand_stock = on_hand_stock + p_quantity WHERE id = v_balance.id;
            ELSE
                UPDATE public.inventory_balances SET damaged_stock = damaged_stock + p_quantity WHERE id = v_balance.id;
            END IF;
        WHEN 'transfer_in' THEN
            UPDATE public.inventory_balances SET on_hand_stock = on_hand_stock + p_quantity WHERE id = v_balance.id;
        WHEN 'sale' THEN
            IF v_available_stock < p_quantity THEN RAISE EXCEPTION 'Insufficient available stock for sale'; END IF;
            UPDATE public.inventory_balances SET on_hand_stock = on_hand_stock - p_quantity WHERE id = v_balance.id;
        WHEN 'supplier_return' THEN
            IF v_available_stock < p_quantity THEN RAISE EXCEPTION 'Insufficient available stock for supplier return'; END IF;
            UPDATE public.inventory_balances SET on_hand_stock = on_hand_stock - p_quantity WHERE id = v_balance.id;
        WHEN 'transfer_out' THEN
            IF v_available_stock < p_quantity THEN RAISE EXCEPTION 'Insufficient available stock for transfer out'; END IF;
            UPDATE public.inventory_balances SET on_hand_stock = on_hand_stock - p_quantity WHERE id = v_balance.id;
        WHEN 'damage' THEN
            IF v_available_stock < p_quantity THEN RAISE EXCEPTION 'Insufficient available stock to mark as damaged'; END IF;
            UPDATE public.inventory_balances SET on_hand_stock = on_hand_stock - p_quantity, damaged_stock = damaged_stock + p_quantity WHERE id = v_balance.id;
        WHEN 'adjustment' THEN
            UPDATE public.inventory_balances SET on_hand_stock = on_hand_stock + p_quantity WHERE id = v_balance.id;
        WHEN 'correction' THEN
            UPDATE public.inventory_balances SET on_hand_stock = on_hand_stock - p_quantity WHERE id = v_balance.id;
        ELSE RAISE EXCEPTION 'Unknown movement type';
    END CASE;

    INSERT INTO public.inventory_movements (
        store_id, variant_id, movement_type, quantity, reference_id, notes, created_by
    )
    VALUES (
        p_store_id, p_variant_id, p_movement_type, p_quantity, p_reference_id, p_notes, auth.uid()
    )
    RETURNING id INTO v_movement_id;

    RETURN v_movement_id;
END;
$function$
